<?php require_once __DIR__.'/../model/doctor_model.php';require_once __DIR__.'/../model/department_model.php';require_once __DIR__.'/../model/appointment_model.php';if($_SESSION['user']['role']!=='patient')exit('Access denied');$dm=new DoctorModel();$deps=new DepartmentModel();$am=new AppointmentModel();$action=$_GET['action'];$error='';$success='';if($action==='doctors'){$departments=$deps->all();$doctors=$dm->all($_GET['department']??'',$_GET['name']??'');require __DIR__.'/../views/doctors.php';exit;}if($action==='book'){$doctor=$dm->find((int)($_GET['doctor_id']??$_POST['doctor_id']??0));if(!$doctor)exit('Doctor not found');if($_SERVER['REQUEST_METHOD']==='POST'){$date=$_POST['appointment_date'];$time=$_POST['appointment_time'];if($date<date('Y-m-d'))$error='Date cannot be in the past.';elseif(!$am->slot($doctor['id'],$date,$time))$error='Time slot is already booked.';else{$am->create($_SESSION['user']['id'],$doctor['id'],$date,$time);$success='Appointment booked successfully.';}}require __DIR__.'/../views/book.php';exit;}if($action==='appointments'){$appointments=$am->patient($_SESSION['user']['id']);require __DIR__.'/../views/appointments.php';exit;}if($action==='cancel'){$am->cancel((int)$_GET['id'],$_SESSION['user']['id']);header('Location:index.php?action=appointments');exit;}
